import { NavLink, useLocation, useNavigate } from 'react-router-dom'
import { useState, useEffect, useCallback, useRef } from 'react'
import {
  LayoutDashboard,
  Bot,
  FolderOpen,
  Settings,
  Zap,
  Sparkles,
  FlaskConical,
  Sun,
  Moon,
  Maximize,
  Minimize,
  BarChart3,
  Clock,
  Users,
  UserCog,
  Search,
  Check,
  ChevronDown,
} from 'lucide-react'
import type { Project } from '../types'
import { useTheme } from '../contexts/ThemeContext'

interface SidebarProps {
  projects: Project[]
}

const navLinkClass = ({ isActive }: { isActive: boolean }) =>
  `flex items-center gap-3 px-4 py-2 text-[13px] rounded-lg mx-2 transition-all ${
    isActive
      ? 'bg-accent-muted text-accent-hover font-medium'
      : 'text-text-secondary hover:text-text hover:bg-surface-2'
  }`

function ProjectSelector({ projects }: { projects: Project[] }) {
  const [open, setOpen] = useState(false)
  const location = useLocation()
  const navigate = useNavigate()
  const ref = useRef<HTMLDivElement>(null)

  const activeProject = projects.find(p => location.pathname.includes(`/projects/${p.id}`))

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  if (projects.length === 0) return null

  return (
    <div ref={ref} className="relative">
      <button
        onClick={() => setOpen(!open)}
        className={`w-full flex items-center gap-2.5 px-3 py-2 text-[13px] rounded-xl border transition-all ${
          activeProject
            ? 'bg-accent/8 border-accent/20 text-accent-hover'
            : 'bg-surface-2/50 border-border text-text-secondary hover:bg-surface-2 hover:text-text'
        }`}
      >
        <FolderOpen className="w-4 h-4 shrink-0" />
        <span className="flex-1 text-left truncate font-medium">
          {activeProject ? activeProject.name : 'Select project...'}
        </span>
        <div className="flex items-center gap-1 shrink-0">
          <span className="text-[9px] bg-surface-2 text-text-muted px-1.5 py-0.5 rounded-full">{projects.length}</span>
          <ChevronDown className={`w-3.5 h-3.5 text-text-muted transition-transform ${open ? 'rotate-180' : ''}`} />
        </div>
      </button>
      {open && (
        <div className="absolute left-0 right-0 bottom-full mb-1 bg-surface border border-border rounded-xl shadow-xl z-50 overflow-hidden">
          <div className="py-1 max-h-[280px] overflow-y-auto">
            {projects.map((p) => {
              const isActive = activeProject?.id === p.id
              return (
                <button
                  key={p.id}
                  onClick={() => { navigate(`/projects/${p.id}`); setOpen(false) }}
                  className={`w-full flex items-center gap-3 px-3 py-2 text-[13px] transition-colors ${
                    isActive
                      ? 'bg-accent/10 text-accent-hover'
                      : 'text-text-secondary hover:bg-surface-2 hover:text-text'
                  }`}
                >
                  <FolderOpen className="w-3.5 h-3.5 shrink-0" />
                  <span className="flex-1 text-left truncate">{p.name}</span>
                  <div className="flex items-center gap-2 shrink-0">
                    {p.agentCount > 0 && (
                      <span className="text-[9px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded-full">
                        {p.agentCount} agents
                      </span>
                    )}
                    {isActive && <Check className="w-3.5 h-3.5 text-accent" />}
                  </div>
                </button>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

export default function Sidebar({ projects }: SidebarProps) {
  const { theme, toggle } = useTheme()
  const [isFullscreen, setIsFullscreen] = useState(false)
  const location = useLocation()

  useEffect(() => {
    const handler = () => setIsFullscreen(!!document.fullscreenElement)
    document.addEventListener('fullscreenchange', handler)
    return () => document.removeEventListener('fullscreenchange', handler)
  }, [])

  const toggleFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen()
    } else {
      document.exitFullscreen()
    }
  }, [])

  // Settings is active for any config-related path
  const isSettingsActive = ['/settings', '/global/claude-md', '/commands', '/rules', '/templates', '/memory', '/backup', '/database'].some(
    p => location.pathname.startsWith(p)
  )
  // Analytics is active for runs and health too
  const isAnalyticsActive = ['/analytics', '/runs', '/health'].some(
    p => location.pathname.startsWith(p)
  )
  // Schedules is active for webhooks too
  const isSchedulesActive = ['/schedules', '/webhooks'].some(
    p => location.pathname.startsWith(p)
  )

  return (
    <aside className="w-[220px] min-w-[220px] h-screen sticky top-0 bg-surface border-r border-border flex flex-col">
      {/* Logo */}
      <div className="px-4 py-3 border-b border-border">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 rounded-lg bg-accent flex items-center justify-center shrink-0">
              <Zap className="w-3.5 h-3.5 text-white" />
            </div>
            <h1 className="text-[14px] font-semibold tracking-tight">Polyglot</h1>
          </div>
          <div className="flex items-center gap-0.5 shrink-0">
            <button
              onClick={toggleFullscreen}
              title={isFullscreen ? 'Exit fullscreen' : 'Fullscreen'}
              className="p-1 rounded-md text-text-muted hover:text-text hover:bg-surface-2 transition-all"
            >
              {isFullscreen ? <Minimize className="w-3.5 h-3.5" /> : <Maximize className="w-3.5 h-3.5" />}
            </button>
            <button
              onClick={toggle}
              title={theme === 'light' ? 'Dark mode' : 'Light mode'}
              className="p-1 rounded-md text-text-muted hover:text-text hover:bg-surface-2 transition-all"
            >
              {theme === 'light' ? <Moon className="w-3.5 h-3.5" /> : <Sun className="w-3.5 h-3.5" />}
            </button>
          </div>
        </div>
      </div>

      {/* Search */}
      <button
        onClick={() => window.dispatchEvent(new KeyboardEvent('keydown', { key: 'k', metaKey: true }))}
        className="mx-3 mt-3 mb-1 flex items-center gap-2 px-3 py-1.5 text-xs text-text-muted bg-surface-2/50 border border-border rounded-lg hover:bg-surface-2 hover:text-text transition-colors"
      >
        <Search className="w-3.5 h-3.5" />
        <span className="flex-1 text-left">Search...</span>
        <kbd className="text-[9px] bg-surface border border-border px-1 py-0.5 rounded font-mono">⌘K</kbd>
      </button>

      {/* Navigation — flat, 8 items */}
      <nav className="flex-1 overflow-y-auto py-3 space-y-0.5">
        <NavLink to="/" className={navLinkClass} end>
          <LayoutDashboard className="w-4 h-4" /> Dashboard
        </NavLink>
        <NavLink to="/agents" className={navLinkClass}>
          <Bot className="w-4 h-4" /> Agents
        </NavLink>
        <NavLink to="/orchestration" className={navLinkClass}>
          <Sparkles className="w-4 h-4" /> Orchestration
        </NavLink>
        <NavLink to="/playground" className={navLinkClass}>
          <FlaskConical className="w-4 h-4" /> Playground
        </NavLink>

        <div className="mx-4 my-2 border-t border-border" />

        <NavLink to="/analytics" className={({ isActive }) =>
          `flex items-center gap-3 px-4 py-2 text-[13px] rounded-lg mx-2 transition-all ${
            isActive || isAnalyticsActive
              ? 'bg-accent-muted text-accent-hover font-medium'
              : 'text-text-secondary hover:text-text hover:bg-surface-2'
          }`
        }>
          <BarChart3 className="w-4 h-4" /> Analytics
        </NavLink>
        <NavLink to="/org-chart" className={navLinkClass}>
          <Users className="w-4 h-4" /> Org Chart
        </NavLink>
        <NavLink to="/hr" className={navLinkClass}>
          <UserCog className="w-4 h-4" /> HR
        </NavLink>
        <NavLink to="/schedules" className={({ isActive }) =>
          `flex items-center gap-3 px-4 py-2 text-[13px] rounded-lg mx-2 transition-all ${
            isActive || isSchedulesActive
              ? 'bg-accent-muted text-accent-hover font-medium'
              : 'text-text-secondary hover:text-text hover:bg-surface-2'
          }`
        }>
          <Clock className="w-4 h-4" /> Schedules
        </NavLink>
        <NavLink to="/settings" className={({ isActive }) =>
          `flex items-center gap-3 px-4 py-2 text-[13px] rounded-lg mx-2 transition-all ${
            isActive || isSettingsActive
              ? 'bg-accent-muted text-accent-hover font-medium'
              : 'text-text-secondary hover:text-text hover:bg-surface-2'
          }`
        }>
          <Settings className="w-4 h-4" /> Settings
        </NavLink>
      </nav>

      {/* Projects — sticky footer */}
      <div className="border-t border-border p-2">
        <ProjectSelector projects={projects} />
      </div>
    </aside>
  )
}

import { useState, memo } from 'react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter'
import { oneDark } from 'react-syntax-highlighter/dist/esm/styles/prism'
import { Copy, Check, Terminal } from 'lucide-react'

function CopyButton({ text, size = 'sm' }: { text: string; size?: 'sm' | 'md' }) {
  const [copied, setCopied] = useState(false)
  const handleCopy = () => {
    navigator.clipboard.writeText(text)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }
  return (
    <button
      onClick={handleCopy}
      className={`flex items-center gap-1 transition-colors ${
        size === 'sm'
          ? 'text-[10px] text-zinc-400 hover:text-zinc-200'
          : 'text-[11px] text-text-muted hover:text-text'
      }`}
      title="Copy code"
    >
      {copied ? (
        <><Check className="w-3 h-3 text-green" /> Copied</>
      ) : (
        <><Copy className="w-3 h-3" /> Copy</>
      )}
    </button>
  )
}

export const MarkdownRenderer = memo(function MarkdownRenderer({ content }: { content: string }) {
  return (
    <div className="markdown-chat">
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        components={{
          code({ className, children, ...props }) {
            const match = /language-(\w+)/.exec(className || '')
            const codeString = String(children).replace(/\n$/, '')
            const isInline = !match && !codeString.includes('\n')
            void props // suppress unused

            if (isInline) {
              return (
                <code className="font-mono text-[0.88em] text-accent bg-accent/8 px-1.5 py-0.5 rounded-md border border-accent/15">
                  {children}
                </code>
              )
            }

            const language = match ? match[1] : 'text'

            return (
              <div className="my-3 rounded-lg border border-border overflow-hidden">
                <div className="flex items-center justify-between px-3 py-1.5 bg-surface-2 border-b border-border">
                  <div className="flex items-center gap-1.5">
                    <Terminal className="w-3 h-3 text-text-muted" />
                    <span className="text-[10px] font-mono text-text-muted tracking-wider">{language}</span>
                  </div>
                  <CopyButton text={codeString} />
                </div>
                <SyntaxHighlighter
                  style={oneDark}
                  language={language}
                  PreTag="div"
                  customStyle={{
                    margin: 0,
                    borderRadius: '0 0 0.5rem 0.5rem',
                    fontSize: '12px',
                    lineHeight: '1.65',
                    background: '#1e1e2e',
                  }}
                  codeTagProps={{ style: { fontFamily: 'var(--font-mono)' } }}
                >
                  {codeString}
                </SyntaxHighlighter>
              </div>
            )
          },
          pre: ({ children }) => <>{children}</>,
          h1: ({ children }) => <h3 className="text-[15px] font-bold text-text mt-4 mb-1.5">{children}</h3>,
          h2: ({ children }) => <h4 className="text-[14px] font-semibold text-text mt-3.5 mb-1.5">{children}</h4>,
          h3: ({ children }) => <h5 className="text-[13px] font-semibold text-text mt-3 mb-1">{children}</h5>,
          h4: ({ children }) => <h6 className="text-[13px] font-medium text-text-secondary mt-2.5 mb-1">{children}</h6>,
          p: ({ children }) => <p className="my-1.5 text-[13px] text-text-secondary leading-relaxed">{children}</p>,
          ul: ({ children }) => <ul className="my-2 space-y-1 list-none">{children}</ul>,
          ol: ({ children, start }) => <ol className="my-2 space-y-1.5 list-none" start={start}>{children}</ol>,
          li: ({ children, ...props }) => {
            const ordered = (props as Record<string, unknown>).ordered
            const index = (props as Record<string, unknown>).index as number | undefined
            return (
              <li className="flex items-start gap-2 text-[13px] text-text-secondary leading-relaxed">
                {ordered ? (
                  <span className="mt-[1px] w-5 h-5 rounded-md bg-surface-2 text-text-muted text-[10px] font-bold flex items-center justify-center shrink-0 border border-border">
                    {(index ?? 0) + 1}
                  </span>
                ) : (
                  <span className="mt-[7px] w-1 h-1 rounded-full bg-text-muted shrink-0" />
                )}
                <span className="flex-1">{children}</span>
              </li>
            )
          },
          a: ({ href, children }) => (
            <a
              href={href}
              target={href?.startsWith('http') ? '_blank' : undefined}
              rel={href?.startsWith('http') ? 'noopener noreferrer' : undefined}
              className="text-accent hover:text-accent-hover font-medium underline decoration-accent/30 underline-offset-2 hover:decoration-accent/60 transition-colors"
            >
              {children}
            </a>
          ),
          strong: ({ children }) => <strong className="font-semibold text-text">{children}</strong>,
          em: ({ children }) => <em className="italic text-text-secondary">{children}</em>,
          blockquote: ({ children }) => (
            <blockquote className="border-l-2 border-accent/40 pl-3 my-2 text-text-secondary italic">
              {children}
            </blockquote>
          ),
          hr: () => <hr className="my-3 border-border" />,
          table: ({ children }) => (
            <div className="my-3 rounded-lg border border-border overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-[12px]">{children}</table>
              </div>
            </div>
          ),
          thead: ({ children }) => <thead className="bg-surface-2">{children}</thead>,
          th: ({ children }) => (
            <th className="px-3 py-2 text-left text-[11px] font-semibold text-text border-b border-border">{children}</th>
          ),
          td: ({ children }) => (
            <td className="px-3 py-2 text-[12px] text-text-secondary border-b border-border/50">{children}</td>
          ),
          tr: ({ children }) => <tr className="border-b border-border last:border-0">{children}</tr>,
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  )
})

