import { useState } from 'react'
import { TabNav } from '../components/PageShell'
import AllCommands from './AllCommands'
import AllRules from './AllRules'

const TABS = [
  { id: 'commands', label: 'Commands' },
  { id: 'rules', label: 'Rules' },
]

export default function CommandsRulesTab() {
  const [tab, setTab] = useState('commands')

  return (
    <div>
      <TabNav tabs={TABS} active={tab} onChange={setTab} />
      {tab === 'commands' && <AllCommands />}
      {tab === 'rules' && <AllRules />}
    </div>
  )
}

import { useState, useEffect, lazy, Suspense } from 'react'
import { useSearchParams } from 'react-router-dom'
import { PageShell, TabNav } from '../components/PageShell'

// Lazy-load tab panels — each loads only when its tab is selected
const GeneralTab = lazy(() => import('./Settings'))
const ClaudeMdTab = lazy(() => import('./GlobalClaudeMd'))
const CommandsRulesTab = lazy(() => import('./CommandsRulesTab'))
const TemplatesTab = lazy(() => import('./TemplateLibrary'))
const MemoryTab = lazy(() => import('./Memory'))
const BackupTab = lazy(() => import('./Backup'))
const DatabaseTab = lazy(() => import('./DatabaseExplorer'))

const TABS = [
  { id: 'general', label: 'General' },
  { id: 'claude-md', label: 'CLAUDE.md' },
  { id: 'commands', label: 'Commands & Rules' },
  { id: 'templates', label: 'Templates' },
  { id: 'memory', label: 'Memory' },
  { id: 'backup', label: 'Backup' },
  { id: 'database', label: 'Database' },
]

interface Props {
  onSave: () => void
}

function Spinner() {
  return (
    <div className="flex items-center justify-center h-48">
      <div className="w-5 h-5 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

export default function SettingsHub({ onSave }: Props) {
  const [searchParams, setSearchParams] = useSearchParams()
  const tabParam = searchParams.get('tab') || 'general'
  const [activeTab, setActiveTab] = useState(tabParam)

  useEffect(() => {
    setActiveTab(tabParam)
  }, [tabParam])

  const handleTabChange = (tab: string) => {
    setActiveTab(tab)
    setSearchParams({ tab }, { replace: true })
  }

  return (
    <PageShell title="Settings" subtitle="Configure Polyglot">
      <TabNav tabs={TABS} active={activeTab} onChange={handleTabChange} />
      <Suspense fallback={<Spinner />}>
        {activeTab === 'general' && <GeneralTab onSave={onSave} />}
        {activeTab === 'claude-md' && <ClaudeMdTab />}
        {activeTab === 'commands' && <CommandsRulesTab />}
        {activeTab === 'templates' && <TemplatesTab />}
        {activeTab === 'memory' && <MemoryTab />}
        {activeTab === 'backup' && <BackupTab />}
        {activeTab === 'database' && <DatabaseTab />}
      </Suspense>
    </PageShell>
  )
}

import { useState, useEffect } from 'react'
import { Clock, Plus, Trash2, Play, Pause, AlertCircle, CheckCircle, XCircle } from 'lucide-react'
import { getSchedules, createSchedule, updateSchedule, deleteSchedule, getGlobalAgents } from '../lib/api'
import type { Schedule } from '../lib/api'
import type { Agent } from '../types'

const CRON_PRESETS = [
  { label: 'Every minute', value: '* * * * *' },
  { label: 'Every 5 minutes', value: '*/5 * * * *' },
  { label: 'Every hour', value: '0 * * * *' },
  { label: 'Every day at 9am', value: '0 9 * * *' },
  { label: 'Every Monday 9am', value: '0 9 * * 1' },
  { label: 'Every 1st of month', value: '0 9 1 * *' },
]

function timeAgo(ts: string | null): string {
  if (!ts) return 'never'
  const diff = Date.now() - new Date(ts).getTime()
  if (diff < 60000) return 'just now'
  if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`
  if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`
  return `${Math.floor(diff / 86400000)}d ago`
}

export default function SchedulesPage() {
  const [schedules, setSchedules] = useState<Schedule[]>([])
  const [agents, setAgents] = useState<Agent[]>([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)
  const [form, setForm] = useState({ name: '', agentName: '', prompt: '', cronExpr: '0 9 * * *' })
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')

  const load = () => {
    setLoading(true)
    Promise.all([getSchedules(), getGlobalAgents()])
      .then(([s, a]) => { setSchedules(s); setAgents(a) })
      .catch(() => {})
      .finally(() => setLoading(false))
  }

  useEffect(() => { load() }, [])

  const handleCreate = async () => {
    if (!form.name || !form.agentName || !form.prompt || !form.cronExpr) {
      setError('All fields are required')
      return
    }
    setSaving(true)
    setError('')
    try {
      await createSchedule(form)
      setShowForm(false)
      setForm({ name: '', agentName: '', prompt: '', cronExpr: '0 9 * * *' })
      load()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create schedule')
    } finally {
      setSaving(false)
    }
  }

  const handleToggle = async (schedule: Schedule) => {
    try {
      await updateSchedule(schedule.id, { enabled: !schedule.enabled })
      load()
    } catch {}
  }

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this schedule?')) return
    try {
      await deleteSchedule(id)
      load()
    } catch {}
  }

  if (loading) return <div className="p-8 text-text-muted">Loading schedules...</div>

  return (
    <div className="max-w-4xl mx-auto p-8 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6" /> Scheduled Runs
          </h1>
          <p className="text-text-muted text-sm mt-1">Agents that run automatically on a cron schedule</p>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg bg-accent text-white hover:bg-accent-hover transition-colors"
        >
          <Plus className="w-4 h-4" /> New Schedule
        </button>
      </div>

      {/* Create Form */}
      {showForm && (
        <div className="bg-surface rounded-xl border border-border p-5 space-y-4">
          <h2 className="text-sm font-semibold">Create Schedule</h2>
          {error && (
            <div className="flex items-center gap-2 text-red-400 text-xs bg-red-500/10 px-3 py-2 rounded-lg">
              <AlertCircle className="w-3.5 h-3.5" /> {error}
            </div>
          )}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs text-text-muted mb-1">Name</label>
              <input
                className="w-full px-3 py-2 text-sm bg-surface-2 border border-border rounded-lg focus:border-accent outline-none"
                placeholder="Daily Status Report"
                value={form.name}
                onChange={e => setForm({ ...form, name: e.target.value })}
              />
            </div>
            <div>
              <label className="block text-xs text-text-muted mb-1">Agent</label>
              <select
                className="w-full px-3 py-2 text-sm bg-surface-2 border border-border rounded-lg focus:border-accent outline-none"
                value={form.agentName}
                onChange={e => setForm({ ...form, agentName: e.target.value })}
              >
                <option value="">Select agent...</option>
                {agents.map(a => (
                  <option key={a.filename} value={a.filename}>{a.name}</option>
                ))}
              </select>
            </div>
          </div>
          <div>
            <label className="block text-xs text-text-muted mb-1">Cron Expression</label>
            <div className="flex gap-2">
              <input
                className="flex-1 px-3 py-2 text-sm bg-surface-2 border border-border rounded-lg focus:border-accent outline-none font-mono"
                placeholder="0 9 * * *"
                value={form.cronExpr}
                onChange={e => setForm({ ...form, cronExpr: e.target.value })}
              />
              <select
                className="px-3 py-2 text-sm bg-surface-2 border border-border rounded-lg outline-none"
                onChange={e => { if (e.target.value) setForm({ ...form, cronExpr: e.target.value }); e.target.value = '' }}
                defaultValue=""
              >
                <option value="">Presets...</option>
                {CRON_PRESETS.map(p => (
                  <option key={p.value} value={p.value}>{p.label}</option>
                ))}
              </select>
            </div>
            <p className="text-[10px] text-text-muted mt-1">Format: minute hour day-of-month month day-of-week</p>
          </div>
          <div>
            <label className="block text-xs text-text-muted mb-1">Prompt</label>
            <textarea
              className="w-full px-3 py-2 text-sm bg-surface-2 border border-border rounded-lg focus:border-accent outline-none min-h-[80px] resize-y"
              placeholder="What should this agent do on each run?"
              value={form.prompt}
              onChange={e => setForm({ ...form, prompt: e.target.value })}
            />
          </div>
          <div className="flex justify-end gap-2">
            <button onClick={() => setShowForm(false)} className="px-4 py-2 text-sm rounded-lg bg-surface-2 hover:bg-surface-2/80">
              Cancel
            </button>
            <button
              onClick={handleCreate}
              disabled={saving}
              className="px-4 py-2 text-sm font-medium rounded-lg bg-accent text-white hover:bg-accent-hover disabled:opacity-50"
            >
              {saving ? 'Creating...' : 'Create Schedule'}
            </button>
          </div>
        </div>
      )}

      {/* Schedule List */}
      <div className="space-y-3">
        {schedules.map(s => (
          <div key={s.id} className="bg-surface rounded-xl border border-border p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <button
