// --- Unified endpoints ---

app.get('/api/unified/agents', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);

  // Load org data (registry + departments) — enrich each agent with
  // level / levelTitle / yearsOfExperience / tier / department / leader flag
  // so the UI doesn't need a second request per row.
  const orgMod = require('./org');
  let registryById = {};
  let departmentsById = {};
  try {
    const registry = orgMod.loadRegistry();
    registryById = registry?.agents || {};
    const deps = orgMod.loadDepartments();
    departmentsById = deps?.departments || {};
  } catch { /* org unavailable — degrade gracefully */ }

  // Token-budget health per row. This matches exactly what AgentHealthBar
  // shows at the top of the agent editor (status + usage + lines + tokens).
  // Computed in-process for every agent using the same checkBudget() that the
  // editor endpoint uses — single source of truth.
  const { checkBudget } = require('./compactor/budget');
  const computeBudgetHealth = (agent) => {
    try {
      if (!agent.raw) return null;
      const check = checkBudget({ agentId: agent.filename, content: agent.raw });
      const linePct = check.actual.lines / Math.max(1, check.budget.lines);
      const charPct = check.actual.chars / Math.max(1, check.budget.chars);
      const usage = Math.max(linePct, charPct);
      let status = 'healthy';
      if (check.violations.length > 0) status = 'over';
      else if (check.warnings.length > 0) status = 'warning';
      else if (usage < 0.2) status = 'sparse';
      const estimatedTokens = Math.ceil(agent.raw.length / 4);
      return {
        status,
        usage,
        actual: check.actual,
        budget: check.budget,
        estimatedTokens,
        sizeKb: Math.round((agent.raw.length / 1024) * 100) / 100,
      };
    } catch { return null; }
  };

  const enrich = (agent) => {
    const rec = registryById[agent.filename] || null;
    const dept = rec?.department || null;
    const deptInfo = dept ? departmentsById[dept] : null;
    const health = computeBudgetHealth(agent);
    return {
      ...agent,
      org: rec ? {
        level: rec.level ?? null,
        levelTitle: rec.levelTitle ?? null,
        yearsOfExperience: rec.yearsOfExperience ?? null,
        experiencePoints: rec.experiencePoints ?? null,
        tier: rec.tier || null,
        title: rec.title || null,
        status: rec.status || null,
        department: dept,
        departmentLabel: deptInfo?.label || null,
        departmentColor: deptInfo?.color || null,
        reportsTo: rec.reportsTo || null,
        isLeader: Boolean(deptInfo && deptInfo.head === agent.filename),
      } : null,
      health,
    };
  };

  const results = [];
  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  for (const agent of globalAgents) {
    results.push(enrich({ ...agent, scope: 'global', scopeLabel: 'Global', projectId: null, projectName: null }));
  }

  for (const project of projects) {
    for (const agent of project.agents) {
      results.push(enrich({ ...agent, scope: 'project', scopeLabel: project.name, projectId: project.id, projectName: project.name }));
    }
  }

  // Category filter (legacy — kept for backwards compat)
  const { category, tags } = req.query;
  let filtered = results;
  if (category) {
    filtered = filtered.filter(a => (a.frontmatter?.category || 'uncategorized') === category);
  }
  if (tags) {
    const tagList = tags.split(',').map(t => t.trim().toLowerCase());
    filtered = filtered.filter(a => {
      const agentTags = (a.frontmatter?.tags || '').split(',').map(t => t.trim().toLowerCase());
      return tagList.some(t => agentTags.includes(t));
    });
  }

  filtered.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
  res.json(filtered);
});

// ── Agent Categories ──────────────────────────────────────────────────────────

// Helper: get all agents across global + projects
function getAllAgentsFlat() {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  return [
    ...listAgents(path.join(CLAUDE_DIR, 'agents')),
    ...projects.flatMap(p => p.agents || []),
  ];
}

// Helper: get custom categories from config
function getCustomCategories() {
  const config = loadConfig();
  return Array.isArray(config.customCategories) ? config.customCategories : [];
}

}

function LeaderBadge() {
  return (
    <span
      className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[9px] font-semibold bg-amber-500/15 text-amber-400 shrink-0 ring-1 ring-amber-400/30"
      title="Department leader"
    >
      <Crown className="w-2.5 h-2.5" />
      Lead
    </span>
  )
}

// Inline budget-health badge — mirrors AgentHealthBar at the top of the
// agent editor. Same status, same colors, same usage% so list and detail
// views are consistent.
function HealthBadge({ health }: { health: UnifiedAgent['health'] }) {
  if (!health) return null
  const style =
    health.status === 'over'     ? 'bg-red/10 text-red ring-red/30'
    : health.status === 'warning' ? 'bg-amber-500/15 text-amber-400 ring-amber-400/30'
    : health.status === 'sparse'  ? 'bg-blue-500/15 text-blue-400 ring-blue-400/30'
    : 'bg-emerald-500/15 text-emerald-400 ring-emerald-400/30'
  const Icon =
    health.status === 'over'     ? AlertTriangle
    : health.status === 'warning' ? AlertTriangle
    : health.status === 'sparse'  ? Info
    : CheckCircle2
  const label =
    health.status === 'over'     ? 'Over'
    : health.status === 'warning' ? 'Near'
    : health.status === 'sparse'  ? 'Sparse'
    : 'Healthy'
  const pct = Math.round(health.usage * 100)
  const tokenStr = health.estimatedTokens >= 1000
    ? `${(health.estimatedTokens / 1000).toFixed(1)}k`
    : `${health.estimatedTokens}`
  const tooltip = [
    `${label} — ${pct}% of budget`,
    `${health.actual.lines}/${health.budget.lines} lines · ${health.sizeKb} KB · ~${tokenStr} tokens`,
  ].join('\n')
  return (
    <span
      className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[9px] font-semibold shrink-0 ring-1 ${style}`}
      title={tooltip}
    >
      <Icon className="w-2.5 h-2.5" />
      {pct}%
    </span>
  )
}

function ScopeBadge({ agent }: { agent: UnifiedAgent }) {
  if (agent.scope === 'global') {
    return (
      <span
        className="inline-flex items-center px-1.5 py-0.5 rounded text-[9px] font-mono font-semibold bg-surface-2 text-text-muted shrink-0"
        title="Global agent"
      >
        G
      </span>
    )
  }
  const name = agent.projectName ?? 'Unknown'
  return (
    <span
      className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[9px] font-mono font-semibold bg-amber-500/10 text-amber-400 shrink-0"
      title={`Project: ${name}`}
    >
      <FolderOpen className="w-2.5 h-2.5" />
      {name}
    </span>
  )
}

