}

function SectionHeader({ icon: Icon, label, count, color = 'text-accent' }: { icon: React.ElementType; label: string; count: number; color?: string }) {
  return (
    <div className="flex items-center gap-2 mb-2">
      <Icon className={`w-3.5 h-3.5 ${color}`} />
      <span className="text-[11px] font-semibold text-text-muted uppercase tracking-wider">{label}</span>
      <span className="text-[10px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded-full">{count}</span>
    </div>
  )
}

// Derive a 1-line tagline from a description: first sentence, soft-capped at 80 chars.
function deriveTagline(description: string): string {
  const text = (description || '').trim().replace(/\s+/g, ' ')
  if (!text) return ''
  // First sentence: first '.', '!', or '?' that ends a word.
  const match = text.match(/^[^.!?]+[.!?]/)
  let s = match ? match[0].trim() : text
  if (s.length > 80) {
    s = s.slice(0, 80).replace(/\s+\S*$/, '') + '…'
  } else if (!match && text.length > 80) {
    s = text.slice(0, 80).replace(/\s+\S*$/, '') + '…'
  }
  return s.replace(/[.!?]$/, '')
}

function AgentRow({
  agent, deleting, onDelete, onCopy, onMove,
}: {
  agent: UnifiedAgent; deleting: boolean; onDelete: (a: UnifiedAgent) => void; onCopy: (a: UnifiedAgent) => void; onMove: (a: UnifiedAgent) => void
}) {
  const editLink = agent.scope === 'global' ? `/global/agents/${agent.filename}` : `/projects/${agent.projectId}/agents/${agent.filename}`
  const tagline = deriveTagline(agent.description)

  return (
    <div className="group flex items-center justify-between bg-surface border border-border rounded-lg px-3 py-2.5 hover:border-accent/20 transition-all">
      <Link to={editLink} className="flex items-center gap-3 flex-1 min-w-0">
        <AgentIcon name={agent.name} uid={`${agent.scope}-${agent.filename}`} size={36} global={agent.scope === 'global'} />
