function decryptToken(ciphertext) {
  if (!ciphertext) return '';
  try {
    const [ivB64, tagB64, encB64] = ciphertext.split(':');
    const key = getMachineKey();
    const iv = Buffer.from(ivB64, 'base64');
    const tag = Buffer.from(tagB64, 'base64');
    const enc = Buffer.from(encB64, 'base64');
    const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
    decipher.setAuthTag(tag);
    return Buffer.concat([decipher.update(enc), decipher.final()]).toString('utf8');
  } catch {
    return '';
  }
}

function ensureDir(dir) {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

// ──────────────────────────────────────────────────────────────────────────
//  Structured logging — rotated at 1 MB
// ──────────────────────────────────────────────────────────────────────────

const LOG_MAX_BYTES = 1024 * 1024;

function log(level, event, meta = {}) {
  try {
    ensureDir(path.dirname(LOG_PATH));
    if (fs.existsSync(LOG_PATH) && fs.statSync(LOG_PATH).size > LOG_MAX_BYTES) {
      fs.renameSync(LOG_PATH, LOG_PATH + '.1');
    }
    const line = JSON.stringify({
      t: new Date().toISOString(),
      level,
      event,
      ...meta,
    }) + '\n';
    fs.appendFileSync(LOG_PATH, line);
  } catch {
    // logging must never throw
  }
}

function tailLog(lines = 200) {
  try {
    if (!fs.existsSync(LOG_PATH)) return [];
    const content = fs.readFileSync(LOG_PATH, 'utf-8');
    const all = content.trim().split('\n').filter(Boolean);
    return all.slice(-lines).map((l) => {
      try { return JSON.parse(l); } catch { return { t: '', level: 'raw', event: l }; }
    });
  } catch {
    return [];
  }
}

// ──────────────────────────────────────────────────────────────────────────
//  Concurrency lock — prevents overlapping backups across restarts
// ──────────────────────────────────────────────────────────────────────────

function acquireLock() {
  ensureDir(path.dirname(LOCK_PATH));
  if (fs.existsSync(LOCK_PATH)) {
    try {
      const stat = fs.statSync(LOCK_PATH);
      if (Date.now() - stat.mtimeMs < LOCK_STALE_MS) {
        return false; // active lock
      }
      // stale — reclaim
      log('warn', 'stale_lock_reclaimed', { ageMs: Date.now() - stat.mtimeMs });
    } catch {}
  }
  try {
    fs.writeFileSync(LOCK_PATH, String(process.pid), { flag: 'w' });
    return true;
  } catch {
    return false;
  }
}

function releaseLock() {
  try {
    if (fs.existsSync(LOCK_PATH)) fs.unlinkSync(LOCK_PATH);
  } catch {}
}

// ──────────────────────────────────────────────────────────────────────────
//  Push error classifier — turns raw git stderr into actionable diagnostics
// ──────────────────────────────────────────────────────────────────────────

/**
 * Classify a git push / clone / auth failure into a stable error code.
 * Codes: REPO_NOT_FOUND | AUTH_INVALID | PERMISSION_DENIED | NETWORK |
 *        NON_FAST_FORWARD | LFS_REQUIRED | UNKNOWN
 */
function classifyGitError(rawMessage) {
  const msg = (rawMessage || '').toLowerCase();

  if (/\b404\b|repository not found|not found\.?\s*$/.test(msg)) {

    return (
      <div className="flex items-center justify-center h-64 text-text-muted">
        <Loader className="w-5 h-5 animate-spin mr-2" />
        Loading backup status...
      </div>
    )
  }

  if (!status) {
    return (
      <div className="p-8 text-red-400">Failed to load backup status</div>
    )
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="px-8 pt-5 pb-4 shrink-0">
        <div className="flex items-center justify-between gap-4 flex-wrap">
          <div className="flex items-center gap-3">
            <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-accent/20 to-purple/20 ring-1 ring-accent/20 flex items-center justify-center">
              <CloudUpload className="w-5 h-5 text-accent" />
            </div>
            <div>
              <h1 className="text-xl font-bold leading-tight">Backup</h1>
              <p className="text-[11px] text-text-muted">
                Protect your agents, memory, and config against data loss
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={refetchStatus}
              className="flex items-center gap-1.5 px-2.5 py-1.5 text-[11px] font-medium text-text-muted hover:text-text bg-surface-2 rounded-lg hover:bg-surface-3 transition-colors"
              title="Refresh status"
            >
              <RefreshCw className="w-3 h-3" /> Refresh
            </button>
            <HealthChip status={status} />
          </div>
        </div>

        {/* Tab bar */}
        <div className="flex items-center gap-1 mt-5 bg-surface-2 p-0.5 rounded-lg w-fit">
          <TabButton active={tab === 'overview'} onClick={() => setTab('overview')}>
            <CloudUpload className="w-3.5 h-3.5" /> Overview
          </TabButton>
          <TabButton active={tab === 'cloud'} onClick={() => setTab('cloud')}>
            <History className="w-3.5 h-3.5" /> Cloud History
          </TabButton>
          <TabButton active={tab === 'snapshots'} onClick={() => setTab('snapshots')}>
            <Archive className="w-3.5 h-3.5" /> Local Snapshots
          </TabButton>
          <TabButton active={tab === 'logs'} onClick={() => setTab('logs')}>
            <Terminal className="w-3.5 h-3.5" /> Logs
          </TabButton>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto px-8 pb-8">
        {tab === 'overview' && <OverviewTab status={status} onRefresh={refetchStatus} />}
        {tab === 'cloud' && <CloudHistoryTab status={status} onRefresh={refetchStatus} />}
        {tab === 'snapshots' && <SnapshotsTab onRefresh={refetchStatus} />}
        {tab === 'logs' && <LogsTab />}
      </div>
    </div>
  )
}

// ── Health chip ──────────────────────────────────────────────────────────────

function HealthChip({ status }: { status: BackupStatus }) {
  if (!status.configured) {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-amber-500/10 text-amber-400 text-xs font-semibold">
        <AlertTriangle className="w-3.5 h-3.5" />
        Not Configured
      </span>
    )
  }
  if (!status.enabled) {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-zinc-500/10 text-zinc-400 text-xs font-semibold">
        <Unplug className="w-3.5 h-3.5" />
        Paused
      </span>
    )
  }
  if (status.pendingQueue > 0) {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-amber-500/10 text-amber-400 text-xs font-semibold">
        <RefreshCw className="w-3.5 h-3.5" />
        {status.pendingQueue} Queued
      </span>
    )
  }
  if (status.lastBackupStatus === 'error') {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-red-500/10 text-red-400 text-xs font-semibold">
        <X className="w-3.5 h-3.5" />
        Error
      </span>
    )
  }
  if (typeof status.pendingChanges === 'number' && status.pendingChanges > 0) {
    return (
      <span
        className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-sky-500/10 text-sky-400 text-xs font-semibold"
        title={
          status.pendingChangesSample.length > 0
            ? `Recent: ${status.pendingChangesSample.join(', ')}${status.pendingChangesScanLimited ? ' (scan capped at 20K files)' : ''}`
            : undefined
        }
      >
        <RefreshCw className="w-3.5 h-3.5" />
        {status.pendingChanges}{status.pendingChangesScanLimited ? '+' : ''} Pending
      </span>
    )
  }
  return (
    <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-emerald-500/10 text-emerald-400 text-xs font-semibold">
      <Check className="w-3.5 h-3.5" />
      Protected
    </span>
  )
}

function TabButton({ active, onClick, children }: {
  active: boolean
  onClick: () => void
  children: React.ReactNode
}) {
  return (
    <button
      onClick={onClick}
      className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded-md transition-colors ${
        active ? 'bg-accent text-white shadow-sm shadow-accent/25' : 'text-text-muted hover:text-text'
      }`}
    >
      {children}
    </button>
  )
