        </div>
      ) : (
        <div className="bg-surface rounded-2xl border border-border overflow-hidden">
          <div className="divide-y divide-border/50">
            {commits.map((commit, idx) => (
              <CommitRow
                key={commit.hash}
                commit={commit}
                isLatest={idx === 0}
