async function previewRestore(commitSha) {
  if (!fs.existsSync(path.join(BACKUP_REPO_DIR, '.git'))) {
    return { ok: false, error: 'No backup repo found' };
  }
  const git = simpleGit(BACKUP_REPO_DIR);
